import { useEffect, useRef, useState } from "react";
import {
  uploadZonePhoto,
  uploadExtraPhoto,
  subscribePhotos,
  resetGame
} from "./firebase";

/* -------------------------------------------------------------
   TYPES
-------------------------------------------------------------- */
type Zone = { id: number; cx: number; cy: number; area: number; rPick: number };
type Photo = { id: number; x: number; y: number; url: string };
type ExtraPhoto = { index: number; x: number; y: number; url: string };

type AppProps = {
  mode: "viewer" | "player";
  sessionId: string;
};

/* -------------------------------------------------------------
   CONSTANTES IMAGE
-------------------------------------------------------------- */
const ORIGINAL_WIDTH = 1280;
const ORIGINAL_HEIGHT = 720;


/* Tes images base64 ici */

const CARTE_FOND_DATA_URL = "data:image/jpeg;base64,";
const MASK_DATA_URL = "data:image/jpeg;base64,";
const LOCO_DATA_URL = "data:image/png;base64,";


/* -------------------------------------------------------------
   COMPRESSION D'IMAGE
-------------------------------------------------------------- */
async function compressImage(
  file: File,
  maxSize = 1280,
  quality = 0.7
): Promise<string> {
  return new Promise(resolve => {
    const img = new Image();
    const reader = new FileReader();

    reader.onload = e => {
      img.src = e.target?.result as string;
    };

    img.onload = () => {
      const canvas = document.createElement("canvas");
      let { width, height } = img;

      if (width > height) {
        if (width > maxSize) {
          height *= maxSize / width;
          width = maxSize;
        }
      } else {
        if (height > maxSize) {
          width *= maxSize / height;
          height = maxSize;
        }
      }

      canvas.width = width;
      canvas.height = height;

      const ctx = canvas.getContext("2d")!;
      ctx.drawImage(img, 0, 0, width, height);

      const compressed = canvas.toDataURL("image/jpeg", quality);
      resolve(compressed);
    };

    reader.readAsDataURL(file);
  });
}

/* -------------------------------------------------------------
   APP
-------------------------------------------------------------- */
export default function App({ mode, sessionId }: AppProps) {
  const [zones, setZones] = useState<Zone[]>([]);
  const [photos, setPhotos] = useState<Photo[]>([]);
  const [extraPhotos, setExtraPhotos] = useState<ExtraPhoto[]>([]);
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [locoPos, setLocoPos] = useState<{ x: number; y: number } | null>(null);

  const [enlargedPhotoId, setEnlargedPhotoId] = useState<number | null>(null);
  const enlargeTimer = useRef<number | null>(null);

  const [viewportWidth, setViewportWidth] = useState(window.innerWidth);
  const [viewportHeight, setViewportHeight] = useState(window.innerHeight);
  const [isPortrait, setIsPortrait] = useState(
    window.innerHeight >= window.innerWidth
  );

  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const mapRef = useRef<HTMLDivElement | null>(null);
  const maskRef = useRef<Uint8Array | null>(null);

  /* -------------------------------------------------------------
     DIMENSIONS
  -------------------------------------------------------------- */
  useEffect(() => {
    const onResize = () => {
      setViewportWidth(window.innerWidth);
      setViewportHeight(window.innerHeight);
      setIsPortrait(window.innerHeight >= window.innerWidth);
    };
    window.addEventListener("resize", onResize);
    window.addEventListener("orientationchange", onResize);
    return () => {
      window.removeEventListener("resize", onResize);
      window.removeEventListener("orientationchange", onResize);
    };
  }, []);

  const imageRatio = ORIGINAL_HEIGHT / ORIGINAL_WIDTH;
  const mapWidth = viewportWidth;
  const mapHeight = mapWidth * imageRatio;

  const contentHeight = isPortrait
    ? mapHeight
    : Math.max(mapHeight * 1.2, viewportHeight * 1.3);
  const topMargin = isPortrait ? 0 : contentHeight * 0.1;
  const bottomMargin = isPortrait ? 0 : contentHeight * 0.1;

  /* -------------------------------------------------------------
     LOAD MASK + FIND ZONES
  -------------------------------------------------------------- */
  useEffect(() => {
    const img = new Image();
    img.src = MASK_DATA_URL;

    img.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = ORIGINAL_WIDTH;
      canvas.height = ORIGINAL_HEIGHT;
      const ctx = canvas.getContext("2d")!;
      ctx.drawImage(img, 0, 0);

      const { data } = ctx.getImageData(0, 0, ORIGINAL_WIDTH, ORIGINAL_HEIGHT);
      const mask = new Uint8Array(ORIGINAL_WIDTH * ORIGINAL_HEIGHT);

      for (let i = 0; i < mask.length; i++) {
        const r = data[i * 4];
        const g = data[i * 4 + 1];
        const b = data[i * 4 + 2];
        mask[i] = r < 50 && g < 50 && b < 50 ? 1 : 0;
      }

      const erode = (src: Uint8Array, passes: number) => {
        let cur = src.slice();
        for (let p = 0; p < passes; p++) {
          const out = new Uint8Array(cur.length);
          for (let y = 1; y < ORIGINAL_HEIGHT - 1; y++) {
            for (let x = 1; x < ORIGINAL_WIDTH - 1; x++) {
              const i = y * ORIGINAL_WIDTH + x;
              if (!cur[i]) continue;
              const n =
                cur[i - 1] &
                cur[i + 1] &
                cur[i - ORIGINAL_WIDTH] &
                cur[i + ORIGINAL_WIDTH];
              out[i] = n;
            }
          }
          cur = out;
        }
        return cur;
      };

      const eroded = erode(mask, 2);
      maskRef.current = eroded;

      const visited = new Uint8Array(mask.length);
      const zList: Zone[] = [];

      const flood = (sx: number, sy: number, id: number) => {
        let stack = [sx, sy];
        let sumX = 0,
          sumY = 0,
          count = 0;
        let minX = sx,
          maxX = sx,
          minY = sy,
          maxY = sy;

        while (stack.length) {
          const y = stack.pop()!;
          const x = stack.pop()!;
          const i = y * ORIGINAL_WIDTH + x;

          if (!eroded[i] || visited[i]) continue;

          visited[i] = 1;
          sumX += x;
          sumY += y;
          count++;

          minX = Math.min(minX, x);
          maxX = Math.max(maxX, x);
          minY = Math.min(minY, y);
          maxY = Math.max(maxY, y);

          if (x > 0) stack.push(x - 1, y);
          if (x < ORIGINAL_WIDTH - 1) stack.push(x + 1, y);
          if (y > 0) stack.push(x, y - 1);
          if (y < ORIGINAL_HEIGHT - 1) stack.push(x, y + 1);
        }

        if (count < 80 || count > 6000) return null;

        return {
          id,
          cx: Math.round(sumX / count),
          cy: Math.round(sumY / count),
          area: count,
          rPick: Math.round(Math.max(maxX - minX, maxY - minY) * 0.55)
        };
      };

      let id = 0;
      for (let y = 0; y < ORIGINAL_HEIGHT; y++) {
        for (let x = 0; x < ORIGINAL_WIDTH; x++) {
          const i = y * ORIGINAL_WIDTH + x;
          if (!visited[i] && eroded[i]) {
            const z = flood(x, y, id);
            if (z) zList.push(z);
            id++;
          }
        }
      }

      setZones(zList);
    };
  }, []);

  /* -------------------------------------------------------------
     SYNC FIREBASE — VIEWER + PLAYER
  -------------------------------------------------------------- */
  useEffect(() => {
    const unsub = subscribePhotos(
      sessionId,
      zoneData => {
        // 1) détecter si une NOUVELLE photo arrive
        const newPhotos = zoneData.filter((p: any) => {
          const exists = photos.find(x => x.id === p.zoneId);
          return !exists;
        });

        // 2) si viewer → afficher en grand 3 sec
        if (mode === "viewer" && newPhotos.length > 0) {
          const p = newPhotos[0];
          setEnlargedPhotoId(p.zoneId);

          if (enlargeTimer.current) clearTimeout(enlargeTimer.current);
          enlargeTimer.current = window.setTimeout(() => {
            setEnlargedPhotoId(null);
          }, 3000);
        }

        // 3) mise à jour standard
        setPhotos(
          zoneData.map((p: any) => ({
            id: p.zoneId,
            x: p.x,
            y: p.y,
            url: p.photoUrl
          }))
        );
      },

      extraData => {
        setExtraPhotos(
          extraData.map((p: any) => ({
            index: p.extraIndex,
            x: p.x,
            y: p.y,
            url: p.photoUrl
          }))
        );
      }
    );

    return unsub;
  }, [sessionId, photos, mode]);

  /* -------------------------------------------------------------
     COORDS
  -------------------------------------------------------------- */
  const toImageCoords = (clientX: number, clientY: number) => {
    if (!mapRef.current) return null;

    const r = mapRef.current.getBoundingClientRect();
    if (clientX < r.left || clientX > r.right) return null;
    if (clientY < r.top || clientY > r.bottom) return null;

    return {
      x: ((clientX - r.left) / r.width) * ORIGINAL_WIDTH,
      y: ((clientY - r.top) / r.height) * ORIGINAL_HEIGHT
    };
  };

  /* -------------------------------------------------------------
     PICK ZONE
  -------------------------------------------------------------- */
  const pickZone = (x: number, y: number) => {
    if (!maskRef.current) return null;

    const xi = Math.round(x);
    const yi = Math.round(y);
    const idx = yi * ORIGINAL_WIDTH + xi;

    if (!maskRef.current[idx]) return null;

    let best: number | null = null;
    let bestDist = 99999;

    for (const z of zones) {
      const base = isPortrait ? 1.9 : 1.4;
      const tol = base * z.rPick;
      const d = Math.hypot(z.cx - x, z.cy - y);

      if (d < tol && d < bestDist) {
        bestDist = d;
        best = z.id;
      }
    }

    return best;
  };

  /* -------------------------------------------------------------
     CAMERA
  -------------------------------------------------------------- */
  const triggerCamera = (zid: number) => {
    if (mode !== "player") return;

    setSelectedId(zid);
    const z = zones.find(z => z.id === zid);
    if (z) setLocoPos({ x: z.cx, y: z.cy });

    if (fileInputRef.current) {
      fileInputRef.current.value = "";
      fileInputRef.current.click();
    }
  };

  const processPhoto = async (file: File) => {
    if (selectedId === null) return;
    const z = zones.find(z => z.id === selectedId);
    if (!z) return;

    const dataUrl = await compressImage(file);

    const url = await uploadZonePhoto(
      sessionId,
      selectedId,
      z.cx,
      z.cy,
      dataUrl
    );

    setEnlargedPhotoId(selectedId);
    if (enlargeTimer.current) clearTimeout(enlargeTimer.current);
    enlargeTimer.current = window.setTimeout(() => {
      setEnlargedPhotoId(null);
    }, 3000);
  };

  /* -------------------------------------------------------------
     EXTRA
  -------------------------------------------------------------- */
  const canAddExtra = photos.length >= 30 && mode === "player";

  const takeExtraPhoto = () => {
    if (!canAddExtra) return;
    setSelectedId(-1);
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
      fileInputRef.current.click();
    }
  };

  const processExtraPhoto = async (file: File) => {
    const index = extraPhotos.length;
    const dataUrl = await compressImage(file);

    const x = 1080 + Math.random() * 140;
    const y = 80 + Math.random() * 140;

    await uploadExtraPhoto(sessionId, index, x, y, dataUrl);
  };

  /* -------------------------------------------------------------
     TAP
  -------------------------------------------------------------- */
  const handleTap = (x: number, y: number) => {
    if (mode !== "player") return;

    if (enlargedPhotoId !== null) {
      setEnlargedPhotoId(null);
      return;
    }

    const coords = toImageCoords(x, y);
    if (!coords) return;

    const zid = pickZone(coords.x, coords.y);
    if (zid !== null) triggerCamera(zid);
  };

  /* -------------------------------------------------------------
     RENDER
  -------------------------------------------------------------- */
  const imgX = (x: number) => (x / ORIGINAL_WIDTH) * mapWidth;
  const imgY = (y: number) => (y / ORIGINAL_HEIGHT) * mapHeight;

  const locoSize = isPortrait ? mapWidth * 0.05 : mapWidth * 0.035;
  const thumbSmall = isPortrait ? mapWidth * 0.03 : mapWidth * 0.03;
  const thumbBig = isPortrait ? mapWidth * 0.1 : mapWidth * 0.08;

  return (
    <div style={{ position: "fixed", inset: 0, background: "#000" }}>
      {/* SCROLL */}
      <div
        style={{
          width: "100%",
          height: "100%",
          overflowX: "hidden",
          overflowY: isPortrait ? "hidden" : "auto",
          touchAction: isPortrait ? "none" : "pan-y"
        }}
      >
        <div style={{ position: "relative", width: "100%", height: contentHeight }}>
          <div style={{ width: "100%", height: topMargin }} />

          {/* MAP */}
          <div
            ref={mapRef}
            onClick={e => handleTap(e.clientX, e.clientY)}
            style={{
              position: "relative",
              width: mapWidth,
              height: mapHeight,
              margin: "0 auto",
              backgroundImage: `url(${CARTE_FOND_DATA_URL})`,
              backgroundSize: "100% 100%",
              backgroundRepeat: "no-repeat"
            }}
          >
            {/* LOCO */}
            {locoPos && (
              <img
                src={LOCO_DATA_URL}
                style={{
                  position: "absolute",
                  left: imgX(locoPos.x) - locoSize / 2,
                  top: imgY(locoPos.y) - locoSize / 2,
                  width: locoSize,
                  height: locoSize,
                  pointerEvents: "none",
                  zIndex: 5
                }}
              />
            )}

            {/* PHOTOS */}
            {photos.map(p => {
              const isBig = enlargedPhotoId === p.id;
              const size = isBig ? thumbBig : thumbSmall;

              return (
                <img
                  key={p.id}
                  src={p.url}
                  onClick={e => {
                    e.stopPropagation();
                    setEnlargedPhotoId(p.id);
                    if (enlargeTimer.current) clearTimeout(enlargeTimer.current);
                    enlargeTimer.current = window.setTimeout(() => {
                      setEnlargedPhotoId(null);
                    }, 3000);
                  }}
                  style={{
                    position: "absolute",
                    left: imgX(p.x) - size / 2,
                    top: imgY(p.y) - size / 2,
                    width: size,
                    height: size,
                    objectFit: "cover",
                    borderRadius: 6,
                    boxShadow: "0 0 2px #000",
                    zIndex: isBig ? 1000 : 10,
                    transition: "all 0.25s"
                  }}
                />
              );
            })}

            {/* PHOTOS EXTRA */}
            {extraPhotos.map((p, i) => (
              <img
                key={i}
                src={p.url}
                style={{
                  position: "absolute",
                  left: imgX(p.x),
                  top: imgY(p.y),
                  width: thumbSmall * 1.2,
                  height: thumbSmall * 1.2,
                  objectFit: "cover",
                  transform: `rotate(${(Math.random() * 10 - 5).toFixed(2)}deg)`,
                  opacity: 0.92,
                  borderRadius: 6,
                  zIndex: 5 + i
                }}
              />
            ))}
          </div>

          <div style={{ width: "100%", height: bottomMargin }} />
        </div>
      </div>

      {/* EXTRA BUTTON */}
      {canAddExtra && (
        <div
          onClick={takeExtraPhoto}
          style={{
            position: "absolute",
            top: mapHeight * 0.15,
            left: mapWidth * 0.78,
            padding: "10px 14px",
            background: "#fff",
            borderRadius: 8,
            fontSize: 16,
            fontWeight: "bold",
            cursor: "pointer",
            zIndex: 2000
          }}
        >
          Plus de souvenir
        </div>
      )}

      {/* NOUVELLE PARTIE */}
      {mode === "viewer" && (
        <div
          onClick={async () => {
            await resetGame(sessionId);
            setPhotos([]);
            setExtraPhotos([]);
            setEnlargedPhotoId(null);
          }}
          style={{
            position: "absolute",
            bottom: 30,
            right: 30,
            padding: "14px 18px",
            background: "#ff4444",
            color: "#fff",
            borderRadius: 10,
            fontSize: 18,
            fontWeight: "bold",
            cursor: "pointer",
            zIndex: 3000,
            boxShadow: "0 3px 8px rgba(0,0,0,0.4)"
          }}
        >
          Nouvelle Partie
        </div>
      )}

      {/* INPUT CAMERA */}
      <input
        ref={fileInputRef}
        type="file"
        accept="image/*"
        capture="environment"
        style={{ display: "none" }}
        onChange={e => {
          const file = e.target.files?.[0];
          if (!file) return;

          if (selectedId === -1) processExtraPhoto(file);
          else processPhoto(file);
        }}
      />
    </div>
  );
}